export function startTown(ctx){
const {THREE,scene,camera,renderer,sites}=ctx;
const $=s=>document.querySelector(s),clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n)),choose=a=>a[Math.floor(Math.random()*a.length)],escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=Number(localStorage.getItem('elsewhere-seed'))||39218;let rng=seed;const random=()=>{rng=(rng*1664525+1013904223)>>>0;return rng/4294967296};
const firstNames=['Mara','Elias','June','Ruth','Caleb','Inez','Theo','Pearl','Nico','Ada','Walter','Lena','Samir','Bea','Jonah','Mina','Silas','Cora','Felix','Mae','Owen','Dalia','Arthur','Kit'];
const jobs=['night nurse','pastor','school librarian','grocery clerk','county mechanic','high-school teacher','sheriff’s deputy','line cook','millwright','florist','bus driver','accountant','retired postmaster','paramedic','music teacher','hotel manager','social worker','farmer','pharmacist','carpenter','court stenographer','dishwasher','radio host','mail carrier'];
const colors=[0xb97961,0x557c7e,0xd4ad6d,0x8272a2,0x6f9267,0xb4778f,0x7186a4,0xc17e4f,0x77a18c,0x9c6e56];
const beliefs=['A quiet Christian faith','Methodist, mostly by habit','Uncertain, but grateful','Secular humanist','The creek has its own kind of holiness','Catholic, with questions','Quaker-influenced pacifism','No doctrine; a personal ethic','A Buddhist reading group','Faithful to St. Oran’s'];
const temperaments=['patient','curious','guarded','generous','restless','wry','tenderhearted','ambitious','methodical','impulsive','steadfast','dreamy'];
const secrets=['Keeps letters from a sibling who left town','Once borrowed money from the church fund and repaid it quietly','Has been applying for work two counties away','Writes anonymous advice for the local radio hour','Has not told their family about a recent diagnosis','Is afraid the family home will be sold','Keeps a second set of books for a struggling neighbor','Still wears a ring from a relationship everyone thinks ended','Knows who damaged the old mill clock','Has been quietly paying a stranger’s heating bill','Wants to leave the faith but fears disappointing their mother','Has a song on a demo tape under another name','Owes the grocer more than they admit','Has been saving for a child who may never come','Was the last person to see the old ferryman alive','Believes the sealed Annex is not empty','Misses someone they claim to dislike','Has an unopened letter in their coat pocket','Has been meeting a friend after their shift','Is considering running for county clerk','Keeps a pressed flower from a first love','Is quietly proud of a mistake they never corrected','Has been teaching themself a language at night','Sometimes talks to the empty house next door'];
