function log(text,kind='Town life'){chronicle.unshift({text,kind,time:`${dayNames[day%7]} · ${clockText()}`});chronicle=chronicle.slice(0,70);renderPeek()}

// The county runs at a steady, light simulation rate; citizen state is independent of the visitor.
const colors3=citizens.map(c=>new THREE.Color(c.color));const actors=new Map();let player={x:5,z:9,yaw:0,pitch:0},started=false,paused=false,dragging=false,lastPointer=null,walkCycle=0,nearCitizen=null,toastTimer=null,bannerTimer=null,filter='All',chronFilter='All',almanacFilter='Everyone',soundOn=true;
const labels=$('#labels'),clockEl=$('#clock'),dayEl=$('#dayLabel'),weatherEl=$('#weather');
function mesh(geometry,material,x,y,z,parent){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function citizenActor(c){const root=new THREE.Group(),coat=new THREE.MeshStandardMaterial({color:c.color,roughness:.82}),skin=new THREE.MeshStandardMaterial({color:0xc79573,roughness:.9}),hair=new THREE.MeshStandardMaterial({color:[0x493a31,0x776047,0x302d2b,0xaaa18c][citizens.indexOf(c)%4],roughness:1}),pants=new THREE.MeshStandardMaterial({color:0x454b45,roughness:.95});scene.add(root);mesh(new THREE.CylinderGeometry(.22,.28,.8,8),coat,0,1.05,0,root);mesh(new THREE.SphereGeometry(.22,10,8),skin,0,1.62,0,root);mesh(new THREE.SphereGeometry(.225,9,7),hair,0,1.76,-.015,root);const legs=[];for(const x of [-.105,.105])legs.push(mesh(new THREE.CylinderGeometry(.075,.09,.55,7),pants,x,.38,0,root));const indicator=mesh(new THREE.SphereGeometry(.055,8,7),new THREE.MeshBasicMaterial({color:0xf0cb79}),0,2.1,0,root);indicator.visible=false;const start=homePos(c);c.x=start.x;c.z=start.z;c.tx=start.x;c.tz=start.z;root.position.set(c.x,0,c.z);actors.set(c.id,{root,legs,indicator,label:null,phase:random()*Math.PI*2})}
citizens.forEach(c=>{citizenActor(c);remember(c,choose(['Woke before the alarm and listened to the county settle.','Dreamed of a road that ran past the creek.','Put the kettle on before the house was fully light.','Thought about a conversation they meant to have.']), '06:42 AM')});
function ensureLabel(c){let a=actors.get(c.id);if(a.label)return a.label;const el=document.createElement('button');el.className='tag';el.innerHTML=`<span class="nm"><i class="mood"></i>${escape(c.name)}</span><span class="act">${escape(c.activity)}</span>`;el.title=`Open ${c.name}'s record`;el.addEventListener('click',()=>openProfile(c));labels.append(el);a.label=el;return el}
function moodColor(c){return c.mood>70?'#a8c987':c.mood>42?'#e4bd76':'#d98b74'}
function setDest(c,kind){let p;if(kind==='sleep'||kind==='home'||kind==='quiet'||kind==='breakfast')p=homePos(c);else if(kind==='work')p=workPos(c);else if(kind==='worship')p=posAt(site('St. Oran’s'));else if(kind==='eat'||kind==='lunch'||kind==='errands')p=posAt(site('Market & Sons'));else if(kind==='socialize'||kind==='argument'||kind==='courtship')p=posAt(site(choose(['The Lantern','Cedar Plaza','County Library','St. Oran’s'])));else p=homePos(c);c.tx=p.x;c.tz=p.z;c.activity=kind}
function arrive(c){if(Math.hypot(c.x-c.tx,c.z-c.tz)<.32){c.x=c.tx;c.z=c.tz;return true}return false}
function targetFor(c){let kind=getAction(c);if(c.actionUntil>gameMinute&&c.activity==='socialize')kind='socialize';if(c.actionUntil>gameMinute&&['argument','courtship','worship'].includes(c.activity))kind=c.activity;if(kind!==c.activity||Math.hypot(c.tx-c.x,c.tz-c.z)<.5)setDest(c,kind)}
function changeMood(c,amount){c.mood=clamp(c.mood+amount);c.stress=clamp(c.stress-amount*.35)}
function pairInteraction(){const active=citizens.filter(c=>c.alive&&['socialize','lunch','worship','errands'].includes(c.activity));if(active.length<2)return;for(let i=0;i<active.length;i++){const a=active[i];if(random()>.11)continue;let options=active.filter(b=>b!==a&&Math.hypot(a.x-b.x,a.z-b.z)<9);if(!options.length)continue;const b=choose(options),rel=a.relationships[b.id];if(rel){let dispute=random()<(.11+a.stress/500+(100-a.mood)/700);if(dispute){rel.value=clamp(rel.value-3);b.relationships[a.id].value=clamp(b.relationships[a.id].value-2);a.stress=clamp(a.stress+8);b.stress=clamp(b.stress+6);a.mood=clamp(a.mood-5);remember(a,`An argument with ${b.name} left a sharp taste.`);remember(b,`Words with ${a.name} went further than intended.`);log(`${a.name} and ${b.name} argued near ${a.activity==='worship'?'St. Oran’s':'the square'}.`,'Relationships')}else{rel.value=clamp(rel.value+1);b.relationships[a.id].value=clamp(b.relationships[a.id].value+1);changeMood(a,1);changeMood(b,1);if(random()<.18){remember(a,`Shared a small kindness with ${b.name}.`);remember(b,`Spent a good few minutes with ${a.name}.`);if(rel.value>78&&rel.type!=='family'&&rel.type!=='siblings'&&rel.type!=='coworkers'&&rel.type!=='quiet crush'){rel.type='close friend';b.relationships[a.id].type='close friend'}if(rel.value>90&&rel.type==='close friend'&&random()<.08){rel.type='quiet crush';b.relationships[a.id].type='quiet crush';log(`${a.name} has begun to see ${b.name} differently.`,'Relationships')}}}}else if(random()<.08){link(a,b,'acquaintance',35);remember(a,`Met ${b.name} properly for the first time.`);remember(b,`Had a pleasant first conversation with ${a.name}.`);log(`${a.name} met ${b.name} during an ordinary stop in town.`,'Relationships')}}}
function needsTick(){for(const c of citizens){if(!c.alive)continue;const old=c.activity,kind=getAction(c);if(kind!==old||arrive(c))setDest(c,kind);const asleep=c.activity==='sleep';c.hunger=clamp(c.hunger+(asleep?.15:.52));c.energy=clamp(c.energy+(asleep?1.7:-.28));c.stress=clamp(c.stress+(c.activity==='work'?.12:-.04));if(c.activity==='work'&&hour()===17&&random()<.24){c.cash=clamp(c.cash+c.salary,0,9999);c.mood=clamp(c.mood+2)}if(c.activity==='eat'||c.activity==='lunch'||c.activity==='breakfast'){if(random()<.18){c.hunger=clamp(c.hunger-23);c.cash=Math.max(0,c.cash-2);remember(c,'A meal and a little quiet helped the day feel possible.')}}if(c.hunger>94){c.mood=clamp(c.mood-1.6);c.stress=clamp(c.stress+1)}if(c.energy<15)c.mood=clamp(c.mood-.7);if(c.activity==='worship'&&old!=='worship'){c.mood=clamp(c.mood+2);remember(c,'Went to St. Oran’s and sat through the whole service.')}}}
function updateWorldEvents(){if(random()>.00085)return;const event=choose([
{title:'The Lantern’s open-mic night',text:'A guitar came out after supper. Two people who had not spoken in weeks stayed to listen.',kind:'Community'},
{title:'A hard rain over the ridge',text:'The creek rose overnight. Neighbors checked porch steps and carried groceries for one another.',kind:'Weather'},
{title:'The mill clock stops',text:'The hands at Paper Mill No. 2 have frozen at 3:10. The morning shift noticed first.',kind:'County mystery'},
{title:'Sunday pantry collection',text:'St. Oran’s pantry is short on flour. By noon, three households have left a sack by the door.',kind:'Community'},
{title:'A family supper goes quiet',text:'One old disagreement surfaced over supper; it will take more than one evening to settle.',kind:'Relationships'},
{title:'The school mural is repainted',text:'Students and a retired art teacher added a blue heron above the gym doors.',kind:'Community'},
{title:'A lost wallet on Juniper Row',text:'Someone found a wallet on the sidewalk and brought it to the sheriff station without a word.',kind:'Town life'}]);worldEvents.unshift({...event,time:`${dayNames[day%7]} · ${clockText()}`});worldEvents=worldEvents.slice(0,12);for(const c of citizens){if(random()<.45){changeMood(c,random()*7-1);remember(c,event.text)}}log(`<b>${event.title}</b> — ${event.text}`,event.kind);const banner=$('#eventBanner');$('#eventKind').textContent=event.kind;$('#eventTitle').textContent=event.title;$('#eventText').textContent=event.text;banner.classList.add('show');clearTimeout(bannerTimer);bannerTimer=setTimeout(()=>banner.classList.remove('show'),9000)}
function simulate(dt){if(speed===0||!started)return;simAccumulator+=dt*4*speed;while(simAccumulator>=1){simAccumulator--;gameMinute++;if(gameMinute>=1440){gameMinute=0;day++;lastWeather=choose(['Still, bright','A soft drizzle','Clouds over the ridge','Warm wind from the creek','A clear, cold morning','Rain moving east']);log(`A new day begins. ${lastWeather} settles over the county.`,'County');}if(gameMinute%10===0)needsTick();if(gameMinute%15===0){pairInteraction();updateWorldEvents()}if(gameMinute%60===0){for(const c of citizens){if(c.cash<20&&random()<.12){c.stress=clamp(c.stress+3);remember(c,'The bills are starting to feel close.')}if(c.mood<35&&random()<.04)c.mood=clamp(c.mood+8)}}}}
function updateActors(dt,t){for(const c of citizens){const a=actors.get(c.id);targetFor(c);const dx=c.tx-c.x,dz=c.tz-c.z,d=Math.hypot(dx,dz),walking=d>.3&&c.activity!=='sleep';if(walking){const step=Math.min(d,dt*(c.activity==='work'?1.5:1.15));c.x+=dx/d*step;c.z+=dz/d*step}a.root.position.set(c.x,walking?Math.abs(Math.sin(t*8+a.phase))*.045:0,c.z);a.root.rotation.y=walking?Math.atan2(dx,dz):Math.sin(t*.7+a.phase)*.08;a.legs.forEach((leg,i)=>leg.rotation.x=walking?Math.sin(t*8+a.phase+i*Math.PI)*.45:0);const pos=new THREE.Vector3(c.x,2.35,c.z).project(camera),el=ensureLabel(c);const visible=pos.z<1&&pos.z>-1&&Math.abs(pos.x)<1.12&&Math.abs(pos.y)<1.12;el.style.display=visible?'block':'none';if(visible){el.style.left=`${(pos.x*.5+.5)*innerWidth}px`;el.style.top=`${(-pos.y*.5+.5)*innerHeight}px`;el.querySelector('.act').textContent=c.activity;el.querySelector('.mood').style.background=moodColor(c);el.style.opacity=nearCitizen===c?'1':'.84'}a.indicator.visible=nearCitizen===c}}
