aily schedule</h3><div class="timeline">${schedule.map(s=>`<div class="tlrow ${s.now?'now':''}"><span class="tm">${s.time}</span><span class="dotcol"><i></i></span><span class="what"><b>${escape(s.kind)}</b><small>${escape(s.where)}</small></span></div>`).join('')}</div><h3>Family, friends & relationships</h3><div>${escape(relNames.join(', ')||'No close ties recorded yet.')}</div><div class="memlist">${relationHtml(c)}</div><h3>Recent memories</h3><div class="memlist">${c.memories.slice(0,6).map(m=>`<div class="mem">${escape(m.text)}<small>${escape(m.day)} · ${escape(m.when)}</small></div>`).join('')||'<div class="mem">A new chapter is beginning.<small>Today</small></div>'}</div><h3>Private</h3><div class="secret"><b>Personal secret</b>${escape(c.secret)}</div><h3>Individual goal</h3><div class="goal"><i>✦</i><span>${escape(c.goal)}</span></div><div class="grid2"><div class="card"><small>Home</small><div class="v">${escape(c.home.name)}</div></div><div class="card"><small>Workplace</small><div class="v">${escape(c.work.name)}</div></div></div>`;$('#profileModal').classList.add('open');$('#profileBody').querySelectorAll('[data-citizen]').forEach(el=>el.addEventListener('click',()=>{const other=citizens.find(x=>x.id===el.dataset.citizen);openProfile(other)}))}

