const {createRequire}=require('node:module');
const fs=require('node:fs');
const path=require('node:path');
const runtime=path.join(process.env.HOME,'.local/share/omgithub-playwright');
const req=createRequire(path.join(runtime,'package.json'));
const {chromium}=req('playwright');
const config=JSON.parse(fs.readFileSync(path.join(runtime,'linux.json'),'utf8'));
(async()=>{
 const browser=await chromium.launch({...config.browser.launchOptions,headless:true});
 const page=await browser.newPage({viewport:{width:1280,height:800},deviceScaleFactor:1});
 const errors=[];
 page.on('pageerror',e=>errors.push(e.message));
 page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 page.on('response',r=>{if(r.status()>=400)errors.push(`HTTP ${r.status()} ${r.url()}`)});
 await page.goto('http://127.0.0.1:4173/',{waitUntil:'load'});
 const introVisible=await page.locator('#start').isVisible();
 const before=await page.locator('#clock').innerText();
 await page.locator('#start').click();
 await page.locator('[data-speed="12"]').click();
 await page.waitForTimeout(5000);
 const state=await page.evaluate(()=>({clock:document.querySelector('#clock')?.textContent,day:document.querySelector('#dayLabel')?.textContent,tags:document.querySelectorAll('#labels .tag').length,peek:document.querySelector('#peek')?.innerText,canvas:!!document.querySelector('canvas'),welcomeGone:document.querySelector('#welcome')?.classList.contains('gone')}));
 await page.screenshot({path:'/tmp/opencode/town-latest.jpg',type:'jpeg',quality:78});
 await page.locator('#almanacBtn').click();
 const almanac=await page.locator('#almanacGrid .person-card').count();
 await page.locator('#almanacGrid .person-card').first().click();
 const profile=await page.locator('#profileName').innerText();
 const profileFields=await page.locator('#profileBody').innerText();
 await page.locator('[data-close="profileModal"]').click();
 await page.locator('#chronicleBtn').click();
 const entries=await page.locator('#chronicleList .entry').count();
 console.log(JSON.stringify({introVisible,before,state,almanac,profile,profileHasIdentity:profileFields.includes('Identity'),entries,errors,screenshot:'/tmp/opencode/town-latest.jpg'},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
