 function relationHtml(c){const rels=Object.values(c.relationships).map(r=>({r,other:citizens.find(x=>x.id===r.id)})).filter(x=>x.other).sort((a,b)=>b.r.value-a.r.value);return rels.length?rels.map(({r,other})=>`<div class="rel" data-citizen="${other.id}"><span class="ricon" style="background:${`#${other.color.toString(16).padStart(6,'0')}`} ">${escape(other.name.slice(0,1))}</span><span><span class="rname">${escape(other.name)}</span><span class="rtype">${escape(r.type)}</span></span><span class="rbar"><i style="width:${r.value}%"></i></span></div>`).join(''):'<p>No close ties yet; ordinary acquaintance has not turned into anything more.</p>'}
